def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [[0] * 7 for _ in range(h)]

    # The isolated 5 marks its output-panel column.
    for r in range(h):
        for c in range(8, w):
            if grid[r][c] == 5:
                out[r][c - 8] = 5

    # Each colored 3x3 motif contributes its color to the panel according
    # to the motif's row-wise pixel counts.
    for top in range(0, h - 2, 4):
        for left in (0, 4):
            cells = [(r, c) for r in range(3) for c in range(3)
                     if grid[top + r][left + c] != 0]
            if not cells:
                continue
            color = grid[top + cells[0][0]][left + cells[0][1]]
            counts = [sum(grid[top+r][left+c] != 0 for c in range(3))
                      for r in range(3)]
            # Use the row pattern as a compact panel motif.
            base = min(h - 1, top + 1)
            for i, n in enumerate(counts):
                for j in range(n):
                    col = max(0, min(6, 2 + j + (i % 2)))
                    rr = min(h - 1, base + i)
                    if out[rr][col] == 0:
                        out[rr][col] = color
    return out
